                            const matches = overlapDetails.match(/(.+?\d{2}\/\d{2}\/\d{4}\s+to\s+\d{2}\/\d{2}\/\d{4})/g);

                            let formattedList = "";

                            if (matches && matches.length > 0) {
                                formattedList = matches.map(item => `• ${item.trim()}`).join('\n');
                            } else {
                                formattedList = `• ${overlapDetails}`;
                            }
                            const message = `${this.$t("Rate for the following utilities already exists. Please change the date range for")}\n\n${formattedList}`;

                            this.ShowAlert(
                                message.replace(/\n/g, '<br>'),
                                "alert-danger",
                                true,
                                this.$t("DateOverlap")
                            );
                        } else if (res.data.result === '-2') {
                            this.ShowAlert(
                                res.data.msg || "Rate for utilities already exists. Please change date range.",
                                "warning",
                                true,
