            // Otherwise, navigate back
            this.navigateBackToClient();
        },

        resetCopyUpdateMode() {
            debugger;

            // Clear selected rate IDs
            this.selectedRateIds = [];

            // Hide the copy/update button section
            this.isShownCopyButton = false;

            // Reset column visibility
            this.Headers.forEach(col => {
                if (
                    col.COLUMN_NAME === "New_Start_Date" ||
                    col.COLUMN_NAME === "New_End_Date" ||
                    col.COLUMN_NAME === "New_Rate" ||
                    col.COLUMN_NAME === "New_Customer_Work_Code" ||
                    col.COLUMN_NAME === "comment"
                ) {
                    col.VISIBLE = false;
                }
            });

            // Clear any temporary data
            this.RateScheduledeListing.forEach(row => {
                if (row.New_Start_Date) delete row.New_Start_Date;
                if (row.New_End_Date) delete row.New_End_Date;
                if (row.New_Rate) delete row.New_Rate;
                if (row.New_Customer_Work_Code) delete row.New_Customer_Work_Code;
                if (row.action) delete row.action;
            });

            // Restore search fields
            this.restoreSearchFields();

            // Force UI refresh
            this.refreshKey++;
        },

        restoreSearchFields() {
            debugger;

            console.log('Restoring search fields...');
            console.log('originalSearchFields:', this.originalSearchFields);

            // ✅ Method 1: Direct restore from saved original
            if (this.originalSearchFields && this.originalSearchFields.length > 0) {
                this.leftSearchFields = JSON.parse(JSON.stringify(this.originalSearchFields));
                console.log('Restored from originalSearchFields:', this.leftSearchFields);
            }
            // ✅ Method 2: Use Schema if method 1 fails
            else if (typeof Schema.bindleftCommonSearchdropdown === 'function') {
                console.log('Using Schema.bindleftCommonSearchdropdown');
                Schema.bindleftCommonSearchdropdown(this, this.clientId);
            }
            // ✅ Method 3: Hardcoded fallback
            else {
                console.log('Using fallback search fields');
                this.leftSearchFields = [{
                    "DATA_TYPE": "string",
                    "DISPLAY_NAME": "Search",
                    "COLUMN_NAME": "SEARCH_TEXT",
                    "IS_SEARCH": true,
                    "SEARCH_TYPE": "text"
                }];
            }

            // Reset search parameters
            this.searchByState = '';
            this.searchByUtility = '';
            this.workCodes = '';
            this.pageNum = 1;

            this.$nextTick(() => {
                setTimeout(() => {
                    $('.left-search, .tg-left-search, .search-panel').show();
                    $('table tbody tr').show();
                    console.log('Search fields should be visible now');
                }, 100);
            });

            this.FetchData();
        },

        // showAllRows() {
        //     // Show all table rows
        //     $('table tbody tr').show();

        //     // Reset search fields if they were hidden
        //     $('.left-search, .tg-left-search, .search-panel').show();

        //     // Reset any hidden search fields
        //     if (this.leftSearchFields.length === 0) {
        //         // Reinitialize search fields if needed
        //         Schema.bindleftCommonSearchdropdown(this, this.clientId);
        //     }
        // },

        resetSearch() {
            // Reset search parameters
            this.searchByState = '';
            this.searchByUtility = '';
            this.workCodes = '';
            this.pageNum = 1;

            // Refresh data
            this.FetchData();
        },

        navigateBackToClient() {
            debugger;

            // Get client ID
            const clientId = this.clientId || this.ClientId;

            if (!clientId) {
                console.error('Client ID not found for navigation');
                this.$router.push('/Client');
                return;
            }

            // Navigate to client update page (not necessarily with RateSchedule hash)
            // This assumes you want to go back to the main client page
            this.$router.push(`/Client/Update/${clientId}`);
        },

        handleSaveComment(updatedData) {
            debugger;
            const index = this.RateScheduledeListing.findIndex(
                item => item.RATE_SCHEDULE_ID === updatedData.RATE_SCHEDULE_ID
            );

            if (index !== -1) {
                this.$set(this.RateScheduledeListing, index, {
                    ...this.RateScheduledeListing[index],
                    COMMENT: updatedData.COMMENT || ""
                });
            }

            this.closeCommentModal();
        },
        closeCommentModal() {
            debugger;
            this.isSetCommnet = false;
        },

        openSelectedRecords(payload) {
            debugger;
            debugger;
            this.isCopyRate = false;
            this.selectedRateIds = payload.ids.map(Number);
            this.isShownCopyButton = true;

            this.Headers.forEach(col => {
                if (
                    col.COLUMN_NAME === "New_Start_Date" ||
                    col.COLUMN_NAME === "New_End_Date" ||
                    col.COLUMN_NAME === "New_Rate" ||
                    col.COLUMN_NAME === "comment" ||
                    col.COLUMN_NAME == "New_Customer_Work_Code"
                ) {
                    col.VISIBLE = true;
                }
            });

            this.RateScheduledeListing.forEach(row => {
                if (this.selectedRateIds.includes(row.RATE_SCHEDULE_ID)) {
                    row.New_Start_Date = payload.newStartDate ?
                        this.$options.filters.formatDate(payload.newStartDate) :
                        '--';
                    row.New_End_Date = payload.newEndDate ?
                        this.$options.filters.formatDate(payload.newEndDate) :
                        '--';
                    row.New_Rate = row.AMOUNT;
                    row.New_Customer_Work_Code = row.Billing_Code;
                    row.action = payload.action || null;
                }
            });

            this.refreshKey++;

            this.$nextTick(() => {
                setTimeout(() => {
                    $('.left-search, .tg-left-search, .search-panel').hide();
                    $('table tbody tr').hide();

                    this.leftSearchFields = [];
                    this.TotalRecords = this.selectedRateIds.length;

                    $('.chkItems:checkbox').each(function () {
                        const id = Number($(this).val());
                        if (payload.ids.includes(id)) {
                            const row = $(this).closest('tr');
                            row.show();
                            row[0].scrollIntoView({
                                behavior: 'smooth',
                                block: 'center'
                            });
                        }
                    });
                }, 150);
            });
        },

        leftCommonSearch: function (value) {
            debugger
            var vm = this;

            vm.PageNumber = value.PageNumber;
            vm.isPaged = 1;

            vm.searchByState = '';
            vm.searchByUtility = '';
            vm.workCodes = '';

            let searchCondition = '';
            if (typeof value.searchCondition !== 'undefined') {
                searchCondition = value.searchConditionJson && value.searchConditionJson !== '' ?
                    value.searchConditionJson :
                    value.searchCondition || "";
            }

            /* ================= MAP SEARCH VALUES ================= */
            if (searchCondition) {

                let params = new URLSearchParams(searchCondition);

                if (params.has('State')) {
                    vm.searchByState = params.get('State');
                }

                if (params.has('UtilityName')) {
                    vm.searchByUtility = params.get('UtilityName');
                }

                if (params.has('Workcode')) {
                    vm.workCodes = params.get('Workcode');
                }

                vm.FetchData();
            } else {
                vm.TotalRecords = 0;
                vm.PageNumber = 1;
                vm.refreshKey += 1;
                vm.FetchData();
            }
        },

        async commonHeaderButtonClick(event) {
            var vm = this;
            switch (event.callbackfunction) {
                case "Inactive":
                    // PRIVILEGE-CHECK: RateSchedule / UpdateStatus (added for mark as inactive in RateScheduleforUsic header)
                    await vm.checkRatePrivilege('RateSchedule', 'UpdateStatus', () => vm.UpdataStatus(1002));
                    break;
                case "AddRateSchedule":
                    // PRIVILEGE-CHECK: RateSchedule / AddRate (added for Add Rate Schedule in RateScheduleforUsic header)
                    await vm.checkRatePrivilege('RateSchedule', 'AddRate', () => vm.AddRateSchedule());
                    break;
                case "Update":
                    // PRIVILEGE-CHECK: RateSchedule / UpdateRates (added for bulk update rates in RateScheduleforUsic header)
                    await vm.checkRatePrivilege('RateSchedule', 'EditRate', () => vm.BulkUpdateRate());
                    break;
                case "CopyRate":
                    // PRIVILEGE-CHECK: RateSchedule / AddRate (added for copy rate in RateScheduleforUsic header)
                    await vm.checkRatePrivilege('RateSchedule', 'UpdateRates', () => vm.CopyRate());
                    break;
                case "ViewHistory":
                    // PRIVILEGE-CHECK: RateSchedule / RateScheduleHistory (added for view history in RateScheduleforUsic header)
                    await vm.checkRatePrivilege('RateSchedule', 'RateScheduleHistory', () => vm.ViewHistory());
                    break;
                case "Remove":
                    // PRIVILEGE-CHECK: RateSchedule / Delete (added for delete rate schedule in RateScheduleforUsic header)
                    await vm.checkRatePrivilege('RateSchedule', 'Delete', () => vm.DeleteData());
                    break;
            }
        },
        DeleteData: function () {
            debugger
            var vm = this;
            var val = "";

            $('.chkItems:checkbox:checked').not("[id^='chkAll']").each(function () {
                if (val.length > 0)
                    val += ',';
                val += $(this).val();
            });

            if (val.length > 0) {
                vm.confirmR(
                    vm.$t("ConfirmDelete"),
                    true,
                    vm.$t("Delete") + " " + vm.$t("RateSchedule"),
                    function () {

                        let url = `ids=${val}&tableName=TALYGEN_BE_rate_schedule&primaryKey=RATE_SCHEDULE_ID`;

                        DataService.Delete(url).then(response => {

                            if (response.data === "DeletedSuccess") {

                                let ids = val.split(',').map(Number);
                                vm.RateScheduledeListing = vm.RateScheduledeListing.filter(
                                    x => !ids.includes(x.RATE_SCHEDULE_ID)
                                );

                                vm.ShowAlert(
                                    vm.$t('DeletedSuccessfully'),
                                    "success",
                                    true,
                                    vm.$t('Alert')
                                );

                            } else {
                                vm.ShowAlert(
                                    vm.$t('DeletedError'),
                                    "failure",
                                    true,
                                    vm.$t('Alert')
                                );
                            }

                        });
                    }
                );
            } else {
                vm.ShowAlert(
                    vm.$t("Selectanyrecordtodelete"),
                    "failure",
                    true,
                    vm.$t("Alert")
                );
            }
        },

        CopyRate() {
            debugger
            var vm = this;
            var val = "";
            $('.chkItems:checkbox:checked').not("[id^='chkAll']").each(async function () {
                if (val.length > 0) {
                    val += ',';
                }
                val += $(this).val();
            });
            let ids = val.split(',').map(Number);
            if (val.length > 0) {
                var vm = this;
                vm.EditData = vm.RateScheduledeListing.filter(x => ids.includes(x.RATE_SCHEDULE_ID))
                vm.isCopyRate = true;
            } else {
                vm.ShowAlert(vm.$t("PleaseSelectAnyRecordsForFurther"), "warning", true, vm.$t("Alert"));
            }

        },
        BulkUpdateRate() {
            debugger
            var vm = this;
            var val = "";
            $('.chkItems:checkbox:checked').not("[id^='chkAll']").each(async function () {
                if (val.length > 0) {
                    val += ',';
                }
                val += $(this).val();
            });
            let ids = val.split(',').map(Number);
            if (val.length > 0) {
                vm.EditData = vm.RateScheduledeListing.filter(x => ids.includes(x.RATE_SCHEDULE_ID));
                vm.isBulkUpdateRate = true;
            } else {
                vm.ShowAlert(vm.$t("PleaseSelectAnyRecordsForFurther"), "warning", true, vm.$t("Alert"));
            }
        },
        UpdataStatus(StatusID, ID) {
            debugger

            var vm = this;
            var val = "";
            $('.chkItems:checkbox:checked').not("[id^='chkAll']").each(async function () {
                if (val.length > 0) {
                    val += ',';
                }
                val += $(this).val();
            });

            vm.confirmR(vm.$t('ChanggingActivetoInactive'), true, false, function (result) {
                var postJSON = {
                    ID: val || ID,
                    StatusId: StatusID,
                    IsFor: "TALYGEN_BE_RATE_SCHEDULE",
                    Module: "RateSchedule",
                    Submodule: "Rate Schedule",
                };
                var objectPostString = JSON.stringify(postJSON);
                DataService.CommonUpdateStatus(objectPostString).then(async response => {
                    if (response.status == 200) {
                        $('.chkItems:checkbox:checked').prop("checked", false).removeAttr('checked');
                        vm.ShowAlert(vm.$t('RecordUpdatedSuccessfully'), "success", true, vm.$t("Alert"));
                        vm.FetchData();

                    }
                });
            })
        },

        async CheckExtraFeatures() {
            //debugger
            var vm = this;
            const params = `featureCode=GET_EXTRA_FEATURE_BILLING&outputType=list`;
            try {
                const response = await DataService.CheckExtraFeatures(params);
                if (response.data) {
                    const features = JSON.parse(response.data);
                    features.forEach(feature => {
                        if (feature.FEATURE_CODE === 'SUBSCRIPTION_BILLING') {
                            vm.IsSubscriptionBilling = true;
                        }
                        if (feature.FEATURE_CODE === 'UTILITY_BILLING') {
                            vm.IsUtilityBilling = true;
                        }
                    });
                }
            } catch (error) {

                console.log("Error checking extra features:", error);
            }
        },

        async FetchData() {
            debugger
            var vueObj = this;
            vueObj.isLoading = true;

            const userDate = vueObj.getUserDate();
            var url = `clientId=${vueObj.clientId}&pageSize=${vueObj.pageSize}&pageNum=${vueObj.pageNum}&sortBy=${vueObj.sortBy}&sortExp=${vueObj.sortExp}&isBillingType=${vueObj.isBillingType}&clientIds=${vueObj.clientIds ?? ''}&workCodes=${vueObj.workCodes ?? ''}&searchByState=${vueObj.searchByState ?? ''}&searchByUtility=${vueObj.searchByUtility ?? ''}&userDate=${userDate}`;

            await DataService.GetWorkCodeMappingList(url).then(function (response) {
                debugger
                if (response.data != "" && response.data != null) {
                    if (response.data.result.length > 0) {
                        vueObj.RateScheduledeListing = response.data.result;
                        vueObj.TotalRecords = response.data.result[0].TOTAL_RECORDS;
                        vueObj.TotalPages = Math.ceil(vueObj.TotalRecords / vueObj.pageSize);
                        vueObj.CurrentPage = vueObj.pageNum;
                        vueObj.noRecord = false;
                    } else {
                        vueObj.noRecord = true;
                        vueObj.TotalRecords = 0;
                        vueObj.RateScheduledeListing = [];
                    }
                } else {
                    vueObj.noRecord = true;
                    vueObj.TotalRecords = 0;
                    vueObj.RateScheduledeListing = [];
                }
            }).catch(error => {
                vueObj.noRecord = true;
                vueObj.TotalRecords = 0;
                vueObj.RateScheduledeListing = [];
            }).finally(() => {
                vueObj.isLoading = false;
            });
        },
        getUserDate() {
            const d = new Date();
            const year = d.getFullYear();
            const month = String(d.getMonth() + 1).padStart(2, '0');
            const day = String(d.getDate()).padStart(2, '0');
            return `${year}-${month}-${day}`; // YYYY-MM-DD
        },
        async actionButtonClick(callbackfunction, item) {
            var vm = this;
            switch (callbackfunction) {
                case 'Edit':
                    // PRIVILEGE-CHECK: RateSchedule / EditRate (added for Edit action in RateScheduleforUsic row actions)
                    await vm.checkRatePrivilege('RateSchedule', 'EditRate', () => vm.Edit(item));
                    break;
                case 'EditDate':
                    // PRIVILEGE-CHECK: RateSchedule / EditRate (added for EditDate action in RateScheduleforUsic row actions)
                    await vm.checkRatePrivilege('RateSchedule', 'EditRate', () => vm.EditDate(item));
                    break;
            }
        },
        renderActions(row) {
            var self = this;
            let rtnActionArray = [];
            const isRecordSelected = row.isSelected;
            self.listActions.forEach(actionItem => {
                let action = {
                    ...actionItem
                };
                if (action.title === 'Edit') {
                    action.isVisible = !isRecordSelected;
                } else if (action.title === 'EditDate') {
                    action.isVisible = isRecordSelected;
                }
                if (action.isVisible !== false) {
                    rtnActionArray.push(action);
                }
            });

            console.log("Rendered Actions: ", rtnActionArray); // Debugging log to verify the returned actions

            return rtnActionArray;
        },
        handleDatesUpdated(updatedDates) {
            debugger;

            // STEP 1: Make columns visible first
            this.Headers.forEach(col => {
                if (col.COLUMN_NAME === "New_Start_Date" || col.COLUMN_NAME === "New_End_Date") {
                    col.VISIBLE = true;
                }
            });

            // STEP 2: Update the data WITH formatted dates
            this.RateScheduledeListing.forEach((row, index) => {
                debugger
                if (this.selectedRateIds.includes(row.RATE_SCHEDULE_ID)) {
                    if (updatedDates.startDate) {
                        // Format the date using $options.filters.formatDate
                        const formattedStartDate = this.$options.filters.formatDate(updatedDates.startDate);
                        this.$set(this.RateScheduledeListing[index], 'New_Start_Date', formattedStartDate);
                    }

                    if (updatedDates.endDate) {
                        // Format the date using $options.filters.formatDate
                        const formattedEndDate = this.$options.filters.formatDate(updatedDates.endDate);
                        this.$set(this.RateScheduledeListing[index], 'New_End_Date', formattedEndDate);
                    }
                }
            });

            // STEP 3: Force UI update
            this.refreshKey++;

            // STEP 4: Close the modal AFTER updating
            this.isSetDate = false;
            this.EditData = []; // Clear edit data
        },
        EditDate(row) {
            debugger
            this.EditData = [row];
            this.isSetDate = true;
        },
        editComment(row) {
            debugger
            this.EditData = this.RateScheduledeListing.find(x => x.RATE_SCHEDULE_ID === row.RATE_SCHEDULE_ID);
            this.isSetCommnet = true
        },
        Edit(row) {
            debugger
            this.EditData = this.RateScheduledeListing.find(x => x.RATE_SCHEDULE_ID === row.RATE_SCHEDULE_ID);
            this.IsAddRate = true;
        },
        EditAddRate(row) {
            debugger
            this.EditData = this.RateScheduledeListing.find(x => x.RATE_SCHEDULE_ID === row.RATE_SCHEDULE_ID);
            this.IsAddRate = true;
        },
        AddRateSchedule() {
            debugger;
            var vm = this;

            vm.EditData = {
                CLIENT_ID: vm.clientId,
                RATE_SCHEDULE_ID: 0
            };

            vm.IsAddRate = true;
        },
        CloseRateCode() {
            var ths = this;
            ths.IsAddRate = false;
            ths.FetchData();
        },

        CloseHistory() {
            var ths = this;
            ths.isViewHistory = false;
            ths.FetchData();
        },
        async ViewHistory() {
            debugger
            this.isViewHistory = true
        },
        // close() {
        //     this.isServices = false
        // },

        sortdata(sortBy) {
            this.sortBy = sortBy;
            var sortExp = 'ASC';
            if (this.sortExp == 'ASC') {
                sortExp = 'DESC';
            }
            this.sortExp = sortExp;
            this.sortBy = sortBy;
            this.sortExp = sortExp;
            this.pageNum = 1;
            this.GroupStart = this.pageNum;
            this.GroupEnd = this.pageNum + 2;
            this.FetchData();
        },
        pagerMethod: function (value) {
            this.pageSize = value.PageSize;
            this.pageNum = value.PageNumber;
            this.FetchData();
        },
    }
}
</script>

